head.script:
scwin.screenId = "jldstf07310";

///////// 1. 변수 및 선언 영역 /////////

scwin.recent_acntg_pd_strt_yymm = undefined;

scwin.recent_acntg_pd_end_yymm = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_recentAcntgPdStrtYymm", fn: function(){ return ((dma_comInfo.get("recentAcntgPdStrtYymm") ?? (() => { throw new Error("unresolved:" + "comInfo.recentAcntgPdStrtYymm"); })()) !== ''); } }, { id: "if_recentAcntgPdEndYymm", fn: function(){ return ((dma_comInfo.get("recentAcntgPdEndYymm") ?? (() => { throw new Error("unresolved:" + "comInfo.recentAcntgPdEndYymm"); })()) !== ''); } }, { id: "if_nparvalstkYn", fn: function(){ return ((dma_comInfo.get("nparvalstkYn") ?? (() => { throw new Error("unresolved:" + "comInfo.nparvalstkYn"); })()) === 'Y'); } }, { id: "if_nparvalstkYn_2", fn: function(){ return ((dma_comInfo.get("nparvalstkYn") ?? (() => { throw new Error("unresolved:" + "comInfo.nparvalstkYn"); })()) === 'N'); } }, { id: "if_nparvalstkYn_3", fn: function(){ return ((dma_comInfo.get("nparvalstkYn") ?? (() => { throw new Error("unresolved:" + "comInfo.nparvalstkYn"); })()) === ''); } }, { id: "if_listTpClssCd", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02' && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "tr_63", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02' && (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '06'); } }, { id: "if_secugrpId", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) !== 'RT'); } }, { id: "tr_102", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) !== 'RT'); } }, { id: "tr_123", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) !== 'RT'); } }, { id: "tr_136", fn: function(){ return ((dma_comInfo.get("secugrpId") ?? (() => { throw new Error("unresolved:" + "comInfo.secugrpId"); })()) !== 'RT'); } }, { id: "if_listTpClssCd_2", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "tr_74", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "tr_95", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "tr_98", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "tr_102", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "tr_123", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "tr_136", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "tr_141", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "tr_146", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !== '02'); } }, { id: "if_listTpClssCd_4_txt", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.listTpClssCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("listTpClssCd")) !== '02'); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb13", fn: function () { return "하한 : " + String(dma_comInfo.get("pershrPubprcLwlmtAmt")) + " 원 ~ 상한 : " + String(dma_comInfo.get("pershrPubprcUplmtAmt")) + " 원"; } },
        { childId: "__rb14", fn: function () { return "하한 : " + String(dma_comInfo.get("lwlmtPubofrSchdlTotamt")) + " 원 ~ 상한 : " + String(dma_comInfo.get("uplmtPubofrSchdlTotamt")) + " 원"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07310.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_print_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_print_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_print_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_print()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07310.btn_print_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_script_dts_List
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_dts_List = async function () {
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_ID, SCREN_PROCES_TP_CD, LD_MKT_TP, COM_NM, BILL_SUBMIT_STRT_DD, BILL_SUBMIT_END_DD", unresolved: "query_param:SCREN_ID,SCREN_PROCES_TP_CD,LD_MKT_TP,COM_NM,BILL_SUBMIT_STRT_DD,BILL_SUBMIT_END_DD" };
    const sbmOptions = {
        id: "tx_script_dts_List",
        method: "post",
        action: "/konex/PubFncKonex.do",
        ref: "dma_scriptDts_ListReq",
        target: "dts_List=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_List_onloaderror'] === 'function') ? scwin['dts_List_onloaderror'] : (typeof scwin['dts_List_onfail'] === 'function') ? scwin['dts_List_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_List_onloadcompleted'] === 'function') ? scwin['dts_List_onloadcompleted'] : ((typeof scwin['dts_List_onsuccess'] === 'function') ? scwin['dts_List_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_List'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07310.tx_script_dts_List" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////
